static int s_lang;

void strings_set_lang(const char *code) {
    static const char *const codes[5] = {"en", "de", "fr", "es", "it"};
    s_lang = 0;
    for (int i = 0; code && i < 5; i++) if (!strcmp(code, codes[i])) s_lang = i;
}

const char *T(str_id_t id) { return id < S__COUNT ? TEXTS[s_lang][id] : ""; }
